// ❓ Quizzone: le domande a risposta multipla e quello che vede ogni telefono.
// Formato compatto: [difficoltà 1-3, domanda, risposta GIUSTA, sbagliata, sbagliata, sbagliata] (il server le mescola).
// Solo fatti stabili e verificati: niente record, prezzi o cariche che cambiano nel tempo.

export type QzCat = 'cultura' | 'geografia' | 'storia' | 'cinema' | 'musica' | 'sport' | 'scienza' | 'cibo' | 'italia' | 'tech' | 'curiosita' | 'piccante';

export const QZ_CATS: Record<QzCat, { name: string; icon: string }> = {
  cultura: { name: 'Cultura generale', icon: '📚' },
  geografia: { name: 'Geografia', icon: '🌍' },
  storia: { name: 'Storia', icon: '🏛️' },
  cinema: { name: 'Cinema e TV', icon: '🎬' },
  musica: { name: 'Musica', icon: '🎵' },
  sport: { name: 'Sport', icon: '⚽' },
  scienza: { name: 'Scienza e natura', icon: '🔬' },
  cibo: { name: 'Cibo e cucina', icon: '🍝' },
  italia: { name: 'Italia', icon: '🇮🇹' },
  tech: { name: 'Tecnologia', icon: '💻' },
  curiosita: { name: 'Curiosità', icon: '🤯' },
  piccante: { name: 'Vietato ai minori', icon: '🌶️' },
};

export interface QzQuestion {
  c: QzCat;
  d: 1 | 2 | 3; // 1 facile, 2 media, 3 difficile
  q: string;
  a: [string, string, string, string]; // a[0] è quella giusta
}

// cosa vede ciascun giocatore (le scelte degli altri solo dopo la rivelazione)
export interface QuizzoneView {
  stage: 'READY' | 'QUESTION' | 'REVEAL' | 'RANKING' | 'END';
  order: string[];
  qNo: number; // domanda in gioco (da 1)
  qCount: number;
  cat: QzCat;
  catName: string;
  catIcon: string;
  diff: 1 | 2 | 3;
  question: string;
  answers: string[] | null; // null mentre si legge la domanda (READY)
  stageEndsAt: number | null;
  answerMs: number; // tempo per rispondere
  answered: string[]; // chi ha già risposto (non cosa)
  myPick: number | null;
  myMs: number | null; // quanto ci ho messo
  correct: number | null; // dalla rivelazione in poi
  picks: Record<string, number> | null; // dalla rivelazione in poi
  fastest: { id: string; ms: number } | null;
  gained: Record<string, number>; // punti presi con l'ultima domanda
  streakBonus: Record<string, number>; // di cui bonus serie
  streaks: Record<string, number>; // risposte giuste di fila
  scores: Record<string, number>;
  prevRank: string[]; // classifica alla tappa precedente (per le frecce su/giù)
  stats: Record<string, { ok: number; fast: number; best: number }>; // giuste, volte più veloce, serie migliore
}

type Raw = [1 | 2 | 3, string, string, string, string, string];
const make = (c: QzCat, list: Raw[]): QzQuestion[] => list.map(([d, q, ...a]) => ({ c, d, q, a: a as QzQuestion['a'] }));

